WHERE c.type = #{type}
ORDER BY c.created_at DESC, c.id DESC
LIMIT #{limit}


WHERE c.status IN #{s}
ORDER BY c.created_at DESC, c.id DESC
LIMIT #{limit}

SELECT r.customer_id, c.phone_enc, c.name, c.last_branch_id, r.attempts
FROM campaign_recipients r JOIN customers c ON c.id = r.customer_id
WHERE r.campaign_id = #{campaignId} AND r.status = 'SENDING' AND r.claimed_at < #{claimedBefore}

mapper.update:
UPDATE campaign_recipients SET status = 'SENT', sent_at = #{now}, error = #{note}, next_attempt_at = NULL,
       attempts = attempts + 1
WHERE campaign_id = #{campaignId} AND customer_id = #{customerId}

UPDATE campaign_recipients SET status = 'FAILED', sent_at = #{now}, error = #{error}, next_attempt_at = NULL,
       attempts = attempts + 1
WHERE campaign_id = #{campaignId} AND customer_id = #{customerId}

UPDATE campaign_recipients SET status = 'PENDING', attempts = attempts + 1, next_attempt_at = #{nextAttemptAt},
       error = #{error}
WHERE campaign_id = #{campaignId} AND customer_id = #{customerId}
